package main

import (
	"fmt"
	"net"
	"os"
	"syscall"
	"time"
	"unsafe"
)

func main() {
	_, err := net.ListenPacket("ip4:icmp", "")
	fmt.Printf("listen err: %v\n", err)
	_, err = net.ListenPacket("ip6:ipv6-icmp", "")
	fmt.Printf("listen err: %v\n", err)

	s, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	if err != nil {
		fmt.Println("socket:", os.NewSyscallError("socket", err))
		return
	}
	if err := syscall.Bind(s, &syscall.SockaddrInet4{}); err != nil {
		fmt.Println("bind:", err)
		return
	}
	f := os.NewFile(uintptr(s), "datagram-oriented icmp")
	c, err := net.FilePacketConn(f)
	f.Close()
	if err != nil {
		fmt.Println("filepacketconn:", err)
		return
	}
	fmt.Printf("local: %v net=%s type=%T\n", c.LocalAddr(), c.LocalAddr().Network(), c)
	rc, _ := c.(syscall.Conn).SyscallConn()
	rc.Control(func(fd uintptr) {
		err := syscall.SetsockoptInt(int(fd), syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1)
		fmt.Println("setsockopt recvttl:", err)
		err = syscall.SetsockoptInt(int(fd), syscall.IPPROTO_IP, syscall.IP_TTL, 64)
		fmt.Println("setsockopt ttl:", err)
	})
	// build echo
	msg := []byte{8, 0, 0, 0, 0x12, 0x34, 0, 1, 'h', 'e', 'l', 'l', 'o', '!'}
	// checksum
	var sum uint32
	for i := 0; i+1 < len(msg); i += 2 {
		sum += uint32(msg[i])<<8 | uint32(msg[i+1])
	}
	for sum>>16 != 0 {
		sum = sum&0xffff + sum>>16
	}
	cs := ^uint16(sum)
	msg[2] = byte(cs >> 8)
	msg[3] = byte(cs)
	_, err = c.WriteTo(msg, &net.UDPAddr{IP: net.ParseIP("192.0.2.1")})
	fmt.Println("write unreachable:", err)
	_, err = c.WriteTo(msg, &net.UDPAddr{IP: net.ParseIP("127.0.0.1")})
	fmt.Println("write:", err)

	buf := make([]byte, 1500)
	oob := make([]byte, 64)
	c.SetReadDeadline(time.Now().Add(500 * time.Millisecond))
	var n, oobn int
	var from syscall.Sockaddr
	var rerr error
	err = rc.Read(func(fd uintptr) bool {
		n, oobn, _, from, rerr = syscall.Recvmsg(int(fd), buf, oob, 0)
		return rerr != syscall.EAGAIN
	})
	fmt.Println("read:", n, oobn, from, rerr, err)
	if err == nil && rerr == nil {
		fmt.Printf("data: % x\n", buf[:n])
		cms, err := syscall.ParseSocketControlMessage(oob[:oobn])
		fmt.Println(cms, err)
		for _, cm := range cms {
			fmt.Println(cm.Header.Level, cm.Header.Type, cm.Data, *(*int32)(unsafe.Pointer(&cm.Data[0])))
		}
	}
	// test deadline error
	c.SetReadDeadline(time.Now().Add(50 * time.Millisecond))
	err = rc.Read(func(fd uintptr) bool {
		n, oobn, _, from, rerr = syscall.Recvmsg(int(fd), buf, oob, 0)
		return rerr != syscall.EAGAIN
	})
	fmt.Printf("timeout read: %v %T\n", err, err)
	if ne, ok := err.(net.Error); ok {
		fmt.Println("timeout?", ne.Timeout())
	}
}
EOF
CGO_ENABLED=0 go build -o t . && ./t"}

