package main

import (
	"os"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

// ANSI SGR attribute codes.
type attribute int

const (
	attrReset attribute = 0
	attrBold  attribute = 1

	fgBlack   attribute = 30
	fgRed     attribute = 31
	fgGreen   attribute = 32
	fgYellow  attribute = 33
	fgBlue    attribute = 34
	fgMagenta attribute = 35
	fgCyan    attribute = 36
	fgWhite   attribute = 37

	fgHiBlack   attribute = 90
	fgHiRed     attribute = 91
	fgHiGreen   attribute = 92
	fgHiYellow  attribute = 93
	fgHiBlue    attribute = 94
	fgHiMagenta attribute = 95
	fgHiCyan    attribute = 96
	fgHiWhite   attribute = 97
)

// resetFor returns the specific reset code of an attribute, or the generic
// reset code when there is none.
func resetFor(a attribute) attribute {
	switch a {
	case 1, 2:
		return 22
	case 3:
		return 23
	case 4:
		return 24
	case 5, 6:
		return 25
	case 7:
		return 27
	case 8:
		return 28
	case 9:
		return 29
	}
	return attrReset
}

// noColor is true when colored output must be suppressed.
var noColor = os.Getenv("NO_COLOR") != "" || os.Getenv("TERM") == "dumb" || !isTerminal(os.Stdout.Fd())

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS),
		uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return errno == 0
}

// style is a set of SGR attributes.
type style []attribute

func newStyle(attrs ...attribute) style { return style(attrs) }

func (s style) open() string {
	parts := make([]string, len(s))
	for i, a := range s {
		parts[i] = strconv.Itoa(int(a))
	}
	return "\x1b[" + strings.Join(parts, ";") + "m"
}

func (s style) close() string {
	parts := make([]string, len(s))
	for i, a := range s {
		parts[i] = strconv.Itoa(int(resetFor(a)))
	}
	return "\x1b[" + strings.Join(parts, ";") + "m"
}

// wrap colorizes an inline string.
func (s style) wrap(text string) string {
	if noColor {
		return text
	}
	return s.open() + text + s.close()
}

// line colorizes a whole line: the style is enabled, the text and a
// newline are written, and finally a full reset is emitted.
func (s style) line(text string) string {
	if noColor {
		return text + "\n"
	}
	return s.open() + text + "\n\x1b[0m"
}
EOF
echo ok"}

