// parseArgs parses the command line in the style of a conventional
// getopt-like parser: short options can be grouped, long options take an
// argument either as the next word or after '=', and '--' terminates option
// processing.
func parseArgs(args []string) (*options, []string, error) {
	opts := &options{Count: 20}
	s := &parseState{args: args, opts: opts}

	for !s.eof() {
		arg := s.pop()

		if arg == "--" {
			s.retargs = append(s.retargs, s.args...)
			break
		}

		if !argumentIsOption(arg) {
			s.retargs = append(s.retargs, arg)
			continue
