		}
		// Only the last short option can consume an argument from the
		// argument list.
		canarg := i+utf8.RuneLen(c) == len(optname)
		if err := s.parseOption(spec, canarg, argument); err != nil {
			return err
		}
		argument = nil
	}
	return nil
}

func (s *parseState) parseOption(spec *optionSpec, canarg bool, argument *string) error {
	if !spec.canArgument() {
		if argument != nil {
			return &parseError{msg: fmt.Sprintf("bool flag `%s' cannot have an argument", spec)}
		}
		if spec.kind == kindHelp {
			return errHelp
		}
		return spec.set(s.opts, "")
	}

	if argument == nil && canarg && !s.eof() {
		arg := s.pop()
		if argumentIsOption(arg) && !(len(arg) > 1 && arg[0] == '-' && arg[1] != '-') {
			return &parseError{msg: fmt.Sprintf("expected argument for flag `%s', but got option `%s'", spec, arg)}
		}
		if arg == "--" {
			return &parseError{msg: fmt.Sprintf("expected argument for flag `%s', but got double dash `--'", spec)}
		}
		argument = &arg
	}

	if argument == nil {
		return &parseError{msg: fmt.Sprintf("expected argument for flag `%s'", spec)}
	}

	arg := *argument
	var err error
	if len(arg) > 0 && arg[0] == '"' {
		arg, err = strconv.Unquote(arg)
	}
	if err == nil {
		err = spec.set(s.opts, arg)
	}
	if err != nil {
		return &parseError{msg: fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", spec, err.Error())}
	}
	return nil
}
