package main

import (
	"net"
	"os"
	"syscall"
	"time"
	"unsafe"
)

const maxIPv4HeaderLen = 60

// icmpConn is a packet connection speaking ICMP, either over an
// unprivileged datagram socket or over a raw socket.
type icmpConn struct {
	c    net.PacketConn
	rc   syscall.RawConn
	ipv4 bool
	raw  bool // raw socket; IPv4 reads include the IP header
	ttl  int
}

// listenICMP opens an ICMP socket. protocol is "udp" for unprivileged
// datagram sockets and "icmp" for raw sockets.
func listenICMP(ipv4 bool, protocol string) (*icmpConn, error) {
	conn := &icmpConn{ipv4: ipv4}
	var err error
	switch protocol {
	case "icmp":
		conn.raw = true
		if ipv4 {
			conn.c, err = net.ListenPacket("ip4:icmp", "")
		} else {
			conn.c, err = net.ListenPacket("ip6:ipv6-icmp", "")
		}
	default:
		conn.c, err = listenDatagramICMP(ipv4)
	}
	if err != nil {
		return nil, err
	}
	sc, ok := conn.c.(syscall.Conn)
	if !ok {
		conn.c.Close()
		return nil, syscall.EINVAL
	}
	conn.rc, err = sc.SyscallConn()
	if err != nil {
		conn.c.Close()
		return nil, err
	}
	return conn, nil
}

func listenDatagramICMP(ipv4 bool) (net.PacketConn, error) {
	family, proto := syscall.AF_INET, syscall.IPPROTO_ICMP
	var sa syscall.Sockaddr = &syscall.SockaddrInet4{}
	if !ipv4 {
		family, proto = syscall.AF_INET6, syscall.IPPROTO_ICMPV6
		sa = &syscall.SockaddrInet6{}
	}
	s, err := syscall.Socket(family, syscall.SOCK_DGRAM, proto)
	if err != nil {
		return nil, os.NewSyscallError("socket", err)
	}
	if err := syscall.Bind(s, sa); err != nil {
		syscall.Close(s)
		return nil, os.NewSyscallError("bind", err)
	}
	f := os.NewFile(uintptr(s), "datagram-oriented icmp")
	c, err := net.FilePacketConn(f)
	f.Close()
	if err != nil {
		return nil, err
	}
	return c, nil
}

func (c *icmpConn) Close() error { return c.c.Close() }

func (c *icmpConn) SetReadDeadline(t time.Time) error { return c.c.SetReadDeadline(t) }

func (c *icmpConn) SetTTL(ttl int) { c.ttl = ttl }

func (c *icmpConn) requestType() byte {
	if c.ipv4 {
		return icmpv4TypeEcho
	}
	return icmpv6TypeEcho
}

func (c *icmpConn) setsockoptInt(level, opt, value int) error {
	var operr error
	err := c.rc.Control(func(fd uintptr) {
		operr = syscall.SetsockoptInt(int(fd), level, opt, value)
	})
	if err != nil {
		return err
	}
	if operr != nil {
		return os.NewSyscallError("setsockopt", operr)
	}
	return nil
}

// EnableTTL asks the kernel to report the TTL / hop limit of received
// packets.
func (c *icmpConn) EnableTTL() error {
	if c.ipv4 {
		return c.setsockoptInt(syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1)
	}
	return c.setsockoptInt(syscall.IPPROTO_IPV6, syscall.IPV6_RECVHOPLIMIT, 1)
}

func (c *icmpConn) applyTTL() error {
	if c.ipv4 {
		return c.setsockoptInt(syscall.IPPROTO_IP, syscall.IP_TTL, c.ttl)
	}
	return c.setsockoptInt(syscall.IPPROTO_IPV6, syscall.IPV6_UNICAST_HOPS, c.ttl)
}

// WriteTo sends an ICMP message to dst with the configured TTL.
func (c *icmpConn) WriteTo(b []byte, dst net.Addr) (int, error) {
	if err := c.applyTTL(); err != nil {
		return 0, err
	}
	return c.c.WriteTo(b, dst)
}

// ReadFrom reads one ICMP message into b. It returns the number of bytes,
// the TTL of the packet (-1 if unknown) and the source address.
func (c *icmpConn) ReadFrom(b []byte) (int, int, net.Addr, error) {
	buf := b
	if c.raw && c.ipv4 {
		buf = make([]byte, maxIPv4HeaderLen+len(b))
	}
	oob := make([]byte, 128)

	var (
		n, oobn int
		from    syscall.Sockaddr
		operr   error
	)
	err := c.rc.Read(func(fd uintptr) bool {
		n, oobn, _, from, operr = syscall.Recvmsg(int(fd), buf, oob, 0)
		return operr != syscall.EAGAIN
	})
	if err != nil {
		return 0, -1, nil, err
	}
	if operr != nil {
		return 0, -1, nil, &net.OpError{Op: "read", Net: c.c.LocalAddr().Network(), Source: c.c.LocalAddr(), Err: os.NewSyscallError("recvmsg", operr)}
	}

	if c.raw && c.ipv4 {
		hdrlen := 0
		if n > 0 {
			hdrlen = int(buf[0]&0x0f) << 2
		}
		if hdrlen > n {
			hdrlen = n
		}
		n = copy(b, buf[hdrlen:n])
	}

	ttl := -1
	if oobn > 0 {
		if cms, err := syscall.ParseSocketControlMessage(oob[:oobn]); err == nil {
			for _, cm := range cms {
				if len(cm.Data) < 4 {
					continue
				}
				if c.ipv4 && cm.Header.Level == syscall.IPPROTO_IP && cm.Header.Type == syscall.IP_TTL {
					ttl = int(*(*int32)(unsafe.Pointer(&cm.Data[0])))
				}
				if !c.ipv4 && cm.Header.Level == syscall.IPPROTO_IPV6 && cm.Header.Type == syscall.IPV6_HOPLIMIT {
					ttl = int(*(*int32)(unsafe.Pointer(&cm.Data[0])))
				}
			}
		}
	}

	var src net.Addr
	switch sa := from.(type) {
	case *syscall.SockaddrInet4:
		src = &net.IPAddr{IP: net.IP(sa.Addr[:])}
	case *syscall.SockaddrInet6:
		src = &net.IPAddr{IP: net.IP(sa.Addr[:])}
	}
	return n, ttl, src, nil
}
