package main

import (
	"encoding/binary"
	"errors"
)

const (
	icmpv4TypeEcho      = 8
	icmpv4TypeEchoReply = 0
	icmpv6TypeEcho      = 128
	icmpv6TypeEchoReply = 129

	icmpHeaderLen = 8
	ipv4HeaderLen = 20
	ipv6HeaderLen = 40
)

var errMessageTooShort = errors.New("message too short")

// echoMessage is an ICMP echo request/reply.
type echoMessage struct {
	Type byte
	Code byte
	ID   int
	Seq  int
	Data []byte
}

// marshalEcho serialises an echo message. The checksum is only computed for
// ICMPv4; for ICMPv6 the kernel fills it in.
func marshalEcho(m *echoMessage, ipv4 bool) []byte {
	b := make([]byte, icmpHeaderLen+len(m.Data))
	b[0] = m.Type
	b[1] = m.Code
	binary.BigEndian.PutUint16(b[4:6], uint16(m.ID))
	binary.BigEndian.PutUint16(b[6:8], uint16(m.Seq))
	copy(b[8:], m.Data)
	if ipv4 {
		s := internetChecksum(b)
		b[2] = byte(s >> 8)
		b[3] = byte(s)
	}
	return b
}

// internetChecksum computes the RFC 1071 one's complement checksum.
func internetChecksum(b []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(b); i += 2 {
		sum += uint32(b[i])<<8 | uint32(b[i+1])
	}
	if len(b)%2 == 1 {
		sum += uint32(b[len(b)-1]) << 8
	}
	for sum>>16 != 0 {
		sum = sum&0xffff + sum>>16
	}
	return ^uint16(sum)
}

// parsedMessage is a decoded ICMP message; Echo is non-nil for echo
// requests and replies.
type parsedMessage struct {
	Type byte
	Code byte
	Echo *echoMessage
}

func parseICMP(b []byte, ipv4 bool) (*parsedMessage, error) {
	if len(b) < 4 {
		return nil, errMessageTooShort
	}
	m := &parsedMessage{Type: b[0], Code: b[1]}
	isEcho := false
	if ipv4 {
		isEcho = m.Type == icmpv4TypeEcho || m.Type == icmpv4TypeEchoReply
	} else {
		isEcho = m.Type == icmpv6TypeEcho || m.Type == icmpv6TypeEchoReply
	}
	if isEcho {
		body := b[4:]
		if len(body) < 4 {
			return nil, errMessageTooShort
		}
		e := &echoMessage{
			Type: m.Type,
			Code: m.Code,
			ID:   int(binary.BigEndian.Uint16(body[0:2])),
			Seq:  int(binary.BigEndian.Uint16(body[2:4])),
		}
		if len(body) > 4 {
			e.Data = make([]byte, len(body)-4)
			copy(e.Data, body[4:])
		}
		m.Echo = e
	}
	return m, nil
}
