type icmpConn struct {
	c    net.PacketConn
	rc   syscall.RawConn
	ipv4 bool
	raw  bool // raw socket; IPv4 reads include the IP header
	ttl  int
}

// listenICMP opens an ICMP socket. protocol is "udp" for unprivileged
// datagram sockets and "icmp" for raw sockets.
func listenICMP(ipv4 bool, protocol string) (*icmpConn, error) {
	conn := &icmpConn{ipv4: ipv4}
	var err error
	switch protocol {
	case "icmp":
		conn.raw = true
		if ipv4 {
			conn.c, err = net.ListenPacket("ip4:icmp", "")
		} else {
			conn.c, err = net.ListenPacket("ip6:ipv6-icmp", "")
		}
	default:
		conn.c, err = listenDatagramICMP(ipv4)
	}
	if err != nil {
		return nil, err
	}
	sc, ok := conn.c.(syscall.Conn)
	if !ok {
		conn.c.Close()
		return nil, syscall.EINVAL
	}
	conn.rc, err = sc.SyscallConn()
	if err != nil {
		conn.c.Close()
		return nil, err
	}
	return conn, nil
}

func listenDatagramICMP(ipv4 bool) (net.PacketConn, error) {
	family, proto := syscall.AF_INET, syscall.IPPROTO_ICMP
	var sa syscall.Sockaddr = &syscall.SockaddrInet4{}
	if !ipv4 {
		family, proto = syscall.AF_INET6, syscall.IPPROTO_ICMPV6
		sa = &syscall.SockaddrInet6{}
	}
	s, err := syscall.Socket(family, syscall.SOCK_DGRAM, proto)
	if err != nil {
		return nil, os.NewSyscallError("socket", err)
	}
	if err := syscall.Bind(s, sa); err != nil {
		syscall.Close(s)
		return nil, os.NewSyscallError("bind", err)
	}
	f := os.NewFile(uintptr(s), "datagram-oriented icmp")
	c, err := net.FilePacketConn(f)
	f.Close()
	if err != nil {
		return nil, err
	}
	return c, nil
}

