package main

import (
	"bytes"
	"crypto/rand"
	"errors"
	"fmt"
	"log"
	"math"
	mrand "math/rand"
	"net"
	"os"
	"sync"
	"syscall"
	"time"
)

const (
	timeSliceLength = 8
	trackerLength   = 16
)

type tracker [trackerLength]byte

func newTracker() tracker {
	var t tracker
	if _, err := rand.Read(t[:]); err != nil {
		r := mrand.New(mrand.NewSource(time.Now().UnixNano()))
		for i := range t {
			t[i] = byte(r.Intn(256))
		}
	}
	// RFC 4122 version 4 / variant bits.
	t[6] = (t[6] & 0x0f) | 0x40
	t[8] = (t[8] & 0x3f) | 0x80
	return t
}

// Packet describes a single echo request/reply.
type Packet struct {
	Rtt    time.Duration
	IPAddr *net.IPAddr
	Addr   string
	Nbytes int
	Seq    int
	TTL    int
	ID     int
}

// Statistics summarises a ping session.
type Statistics struct {
	PacketsRecv           int
	PacketsSent           int
	PacketsRecvDuplicates int
	PacketLoss            float64
	IPAddr                *net.IPAddr
	Addr                  string
	Rtts                  []time.Duration
	MinRtt                time.Duration
	MaxRtt                time.Duration
	AvgRtt                time.Duration
	StdDevRtt             time.Duration
}

// Pinger sends ICMP echo requests and gathers the replies.
type Pinger struct {
	Interval time.Duration
	Timeout  time.Duration
	Count    int
	Size     int
	TTL      int

	PacketsSent           int
	PacketsRecv           int
	PacketsRecvDuplicates int

	OnSetup         func()
	OnSend          func(*Packet)
	OnRecv          func(*Packet)
	OnFinish        func(*Statistics)
	OnDuplicateRecv func(*Packet)

	addr     string
	ipaddr   *net.IPAddr
	ipv4     bool
	network  string
	protocol string
	id       int
	sequence int

	trackers []tracker
	awaiting map[tracker]map[int]struct{}

	done chan struct{}
	lock sync.Mutex

	statsMu   sync.RWMutex
	rtts      []time.Duration
	minRtt    time.Duration
	maxRtt    time.Duration
	avgRtt    time.Duration
	stdDevRtt time.Duration
	stddevm2  time.Duration

	logger *log.Logger
}

// NewPinger creates a pinger for addr and resolves it.
func NewPinger(addr string) (*Pinger, error) {
	p := newPinger(addr)
	return p, p.Resolve()
}

func newPinger(addr string) *Pinger {
	r := mrand.New(mrand.NewSource(time.Now().UnixNano()))
	first := newTracker()
	awaiting := map[tracker]map[int]struct{}{first: {}}
	return &Pinger{
		Count:    -1,
		Interval: time.Second,
		Size:     timeSliceLength + trackerLength,
		Timeout:  time.Duration(math.MaxInt64),
		TTL:      64,

		addr:     addr,
		done:     make(chan struct{}),
		id:       r.Intn(math.MaxUint16),
		trackers: []tracker{first},
		awaiting: awaiting,
		network:  "ip",
		protocol: "udp",
		logger:   log.New(os.Stderr, "", log.LstdFlags),
	}
}

func (p *Pinger) Addr() string          { return p.addr }
func (p *Pinger) IPAddr() *net.IPAddr   { return p.ipaddr }
func (p *Pinger) Privileged() bool      { return p.protocol == "icmp" }

// SetPrivileged selects raw ICMP sockets (true) or unprivileged datagram
// ICMP sockets (false).
func (p *Pinger) SetPrivileged(privileged bool) {
	if privileged {
		p.protocol = "icmp"
	} else {
		p.protocol = "udp"
	}
}

// Resolve looks up the target address.
func (p *Pinger) Resolve() error {
	if len(p.addr) == 0 {
		return errors.New("addr cannot be empty")
	}
	ipaddr, err := net.ResolveIPAddr(p.network, p.addr)
	if err != nil {
		return err
	}
	p.ipv4 = len(ipaddr.IP.To4()) == net.IPv4len
	p.ipaddr = ipaddr
	return nil
}

// Stop terminates a running pinger.
func (p *Pinger) Stop() {
	p.lock.Lock()
	defer p.lock.Unlock()

	open := true
	select {
	case _, open = <-p.done:
	default:
	}
	if open {
		close(p.done)
	}
}

func (p *Pinger) Statistics() *Statistics {
	p.statsMu.RLock()
	defer p.statsMu.RUnlock()
	sent := p.PacketsSent
	loss := float64(sent-p.PacketsRecv) / float64(sent) * 100
	return &Statistics{
		PacketsSent:           sent,
		PacketsRecv:           p.PacketsRecv,
		PacketsRecvDuplicates: p.PacketsRecvDuplicates,
		PacketLoss:            loss,
		Rtts:                  p.rtts,
		Addr:                  p.addr,
		IPAddr:                p.ipaddr,
		MaxRtt:                p.maxRtt,
		MinRtt:                p.minRtt,
		AvgRtt:                p.avgRtt,
		StdDevRtt:             p.stdDevRtt,
	}
}

func (p *Pinger) updateStatistics(pkt *Packet) {
	p.statsMu.Lock()
	defer p.statsMu.Unlock()

	p.PacketsRecv++
	p.rtts = append(p.rtts, pkt.Rtt)

	if p.PacketsRecv == 1 || pkt.Rtt < p.minRtt {
		p.minRtt = pkt.Rtt
	}
	if pkt.Rtt > p.maxRtt {
		p.maxRtt = pkt.Rtt
	}

	// Welford's online algorithm for the running mean and variance.
	n := time.Duration(p.PacketsRecv)
	delta := pkt.Rtt - p.avgRtt
	p.avgRtt += delta / n
	delta2 := pkt.Rtt - p.avgRtt
	p.stddevm2 += delta * delta2
	p.stdDevRtt = time.Duration(math.Sqrt(float64(p.stddevm2 / n)))
}

func (p *Pinger) finish() {
	if handler := p.OnFinish; handler != nil {
		handler(p.Statistics())
	}
}

// Run sends echo requests until Count replies were received, the timeout
// elapsed or Stop was called.
func (p *Pinger) Run() error {
	if p.Size < timeSliceLength+trackerLength {
		return fmt.Errorf("size %d is less than minimum required size %d", p.Size, timeSliceLength+trackerLength)
	}
	if p.ipaddr == nil {
		if err := p.Resolve(); err != nil {
			return err
		}
	}
	conn, err := listenICMP(p.ipv4, p.protocol)
	if err != nil {
		p.Stop()
		return err
	}
	defer conn.Close()

	conn.SetTTL(p.TTL)
	return p.run(conn)
}

func (p *Pinger) run(conn *icmpConn) error {
	if err := conn.EnableTTL(); err != nil {
		return err
	}
	defer p.finish()

	recv := make(chan *rawPacket, 5)
	defer close(recv)

	if handler := p.OnSetup; handler != nil {
		handler()
	}

	var (
		wg      sync.WaitGroup
		errOnce sync.Once
		firstErr error
	)
	record := func(err error) {
		if err != nil {
			errOnce.Do(func() { firstErr = err })
		}
	}

	wg.Add(2)
	go func() {
		defer wg.Done()
		defer p.Stop()
		record(p.recvICMP(conn, recv))
	}()
	go func() {
		defer wg.Done()
		defer p.Stop()
		record(p.runLoop(conn, recv))
	}()
	wg.Wait()
	return firstErr
}

func (p *Pinger) runLoop(conn *icmpConn, recvCh <-chan *rawPacket) error {
	timeout := time.NewTicker(p.Timeout)
	interval := time.NewTicker(p.Interval)
	defer func() {
		interval.Stop()
		timeout.Stop()
	}()

	if err := p.sendICMP(conn); err != nil {
		return err
	}

	for {
		select {
		case <-p.done:
			return nil

		case <-timeout.C:
			return nil

		case r := <-recvCh:
			if err := p.processPacket(r); err != nil {
				p.logger.Printf("FATAL: processing received packet: %s", err)
			}

		case <-interval.C:
			if p.Count > 0 && p.PacketsSent >= p.Count {
				interval.Stop()
				continue
			}
			if err := p.sendICMP(conn); err != nil {
				p.logger.Printf("FATAL: sending packet: %s", err)
			}
		}
		if p.Count > 0 && p.PacketsRecv >= p.Count {
			return nil
		}
	}
}

type rawPacket struct {
	bytes  []byte
	nbytes int
	ttl    int
}

// expBackoff yields randomised, exponentially growing read deadlines so
// that the receiver notices a stop request promptly without spinning.
type expBackoff struct {
	baseDelay time.Duration
	maxExp    int64
	c         int64
}

func (b *expBackoff) Get() time.Duration {
	if b.c < b.maxExp {
		b.c++
	}
	return b.baseDelay * time.Duration(mrand.Int63n(1<<b.c))
}

func (p *Pinger) messageLength() int {
	if p.ipv4 {
		return p.Size + icmpHeaderLen + ipv4HeaderLen
	}
	return p.Size + icmpHeaderLen + ipv6HeaderLen
}

func (p *Pinger) recvICMP(conn *icmpConn, recv chan<- *rawPacket) error {
	backoff := expBackoff{baseDelay: 50 * time.Microsecond, maxExp: 11}
	delay := backoff.Get()

	for {
		select {
		case <-p.done:
			return nil
		default:
			buf := make([]byte, p.messageLength())
			if err := conn.SetReadDeadline(time.Now().Add(delay)); err != nil {
				return err
			}
			n, ttl, _, err := conn.ReadFrom(buf)
			if err != nil {
				if neterr, ok := err.(net.Error); ok && neterr.Timeout() {
					delay = backoff.Get()
					continue
				}
				return err
			}

			select {
			case <-p.done:
				return nil
			case recv <- &rawPacket{bytes: buf, nbytes: n, ttl: ttl}:
			}
		}
	}
}

func timeToBytes(t time.Time) []byte {
	nsec := t.UnixNano()
	b := make([]byte, 8)
	for i := uint8(0); i < 8; i++ {
		b[i] = byte((nsec >> ((7 - i) * 8)) & 0xff)
	}
	return b
}

func bytesToTime(b []byte) time.Time {
	var nsec int64
	for i := uint8(0); i < 8; i++ {
		nsec += int64(b[i]) << ((7 - i) * 8)
	}
	return time.Unix(nsec/1000000000, nsec%1000000000)
}

func (p *Pinger) currentTracker() tracker {
	return p.trackers[len(p.trackers)-1]
}

func (p *Pinger) sendICMP(conn *icmpConn) error {
	var dst net.Addr = p.ipaddr
	if p.protocol == "udp" {
		dst = &net.UDPAddr{IP: p.ipaddr.IP, Zone: p.ipaddr.Zone}
	}

	current := p.currentTracker()
	data := append(timeToBytes(time.Now()), current[:]...)
	if remain := p.Size - timeSliceLength - trackerLength; remain > 0 {
		data = append(data, bytes.Repeat([]byte{1}, remain)...)
	}

	msg := marshalEcho(&echoMessage{
		Type: conn.requestType(),
		Code: 0,
		ID:   p.id,
		Seq:  p.sequence,
		Data: data,
	}, p.ipv4)

	for {
		if _, err := conn.WriteTo(msg, dst); err != nil {
			if neterr, ok := err.(*net.OpError); ok {
				if neterr.Err == syscall.ENOBUFS {
					continue
				}
			}
			return err
		}
		if handler := p.OnSend; handler != nil {
			handler(&Packet{
				Nbytes: len(msg),
				IPAddr: p.ipaddr,
				Addr:   p.addr,
				Seq:    p.sequence,
				ID:     p.id,
			})
		}
		p.awaiting[current][p.sequence] = struct{}{}
		p.PacketsSent++
		p.sequence++
		if p.sequence > 65535 {
			next := newTracker()
			p.trackers = append(p.trackers, next)
			p.awaiting[next] = make(map[int]struct{})
			p.sequence = 0
		}
		return nil
	}
}

func (p *Pinger) matchID(id int) bool {
	// Datagram ICMP sockets rewrite the identifier, so it can only be
	// checked for raw sockets.
	if p.protocol == "icmp" && id != p.id {
		return false
	}
	return true
}

func (p *Pinger) lookupTracker(data []byte) (tracker, bool) {
	var t tracker
	copy(t[:], data[timeSliceLength:timeSliceLength+trackerLength])
	for _, known := range p.trackers {
		if known == t {
			return t, true
		}
	}
	return t, false
}

func (p *Pinger) processPacket(recv *rawPacket) error {
	receivedAt := time.Now()

	m, err := parseICMP(recv.bytes[:recv.nbytes], p.ipv4)
	if err != nil {
		return fmt.Errorf("error parsing icmp message: %w", err)
	}

	if p.ipv4 && m.Type != icmpv4TypeEchoReply || !p.ipv4 && m.Type != icmpv6TypeEchoReply {
		// Not an echo reply; ignore it.
		return nil
	}
	if m.Echo == nil {
		return fmt.Errorf("invalid ICMP echo reply; type: '%d'", m.Type)
	}
