	if len(echo.Data) < timeSliceLength+trackerLength {
		return fmt.Errorf("insufficient data received; got: %d %v", len(echo.Data), echo.Data)
	}

	t, ok := p.lookupTracker(echo.Data)
	if !ok {
		return nil
	}

	timestamp := bytesToTime(echo.Data[:timeSliceLength])
	inPkt.Rtt = receivedAt.Sub(timestamp)
	inPkt.Seq = echo.Seq

	if _, inflight := p.awaiting[t][echo.Seq]; !inflight {
		p.PacketsRecvDuplicates++
		if handler := p.OnDuplicateRecv; handler != nil {
			handler(inPkt)
		}
		return nil
