package main

import (
	"testing"
	"time"
)

func TestStatisticsWelford(t *testing.T) {
	cases := []struct {
		rtts   []int64
		avg    string
		stddev string
	}{
		{[]int64{48757, 112178, 89887}, "83.607µs", "26.269µs"},
		{[]int64{158694, 63639, 68413, 87115, 76743, 88937, 71594, 132599, 108445, 77504,
			75549, 72445, 87350, 91372, 73873, 83098, 74510, 121802, 106914, 104370}, "91.249µs", "23.729µs"},
		{[]int64{135233, 69265, 80520}, "95.006µs", "28.813µs"},
	}
	for _, c := range cases {
		p := newPinger("localhost")
		for _, r := range c.rtts {
			p.updateStatistics(&Packet{Rtt: time.Duration(r)})
		}
		s := p.Statistics()
		if s.AvgRtt.String() != c.avg || s.StdDevRtt.String() != c.stddev {
			t.Errorf("rtts %v: got avg=%s stddev=%s, want avg=%s stddev=%s",
				c.rtts, s.AvgRtt, s.StdDevRtt, c.avg, c.stddev)
		}
	}
}

func TestParseArgs(t *testing.T) {
	cases := []struct {
		args []string
		err  string
		rest []string
	}{
		{[]string{"-c", "3", "host"}, "", []string{"host"}},
		{[]string{"-Pc1", "host"}, "expected argument for flag `-c, --count'", nil},
		{[]string{"-c", "-P"}, "expected argument for flag `-c, --count', but got option `-P'", nil},
		{[]string{"-c", "--"}, "expected argument for flag `-c, --count', but got double dash `--'", nil},
		{[]string{"--count=x"}, "invalid argument for flag `-c, --count' (expected int): strconv.ParseInt: parsing \"x\": invalid syntax", nil},
		{[]string{"-P=1"}, "bool flag `-P, --privilege' cannot have an argument", nil},
		{[]string{"--nope"}, "unknown flag `nope'", nil},
		{[]string{"-c", "-5", "--", "-h"}, "", []string{"-h"}},
	}
	for _, c := range cases {
		_, rest, err := parseArgs(c.args)
		msg := ""
		if err != nil {
			msg = err.Error()
		}
		if msg != c.err {
			t.Errorf("%v: got error %q, want %q", c.args, msg, c.err)
		}
		if c.err == "" && len(rest) != len(c.rest) {
			t.Errorf("%v: got rest %v, want %v", c.args, rest, c.rest)
		}
	}
}
EOF
go test ./... 2>&1 | tail -5"}

